import React, { useEffect, useRef, useState } from "react";
import FileUploadIcon from "@mui/icons-material/FileUpload";
import EditIcon from "@mui/icons-material/Edit";
import PdfLogo from "../../assets/gym_guide/pdf_logo.png";
import http, { uploadImage } from "../../services/utility";
import { apisPath } from "../../utils/path";
import { openSuccessTicker } from "../../redux/reducer/SuccessTickerReducer";
import { openTicker } from "../../redux/reducer/ErrorTickerReducer";
import { useDispatch } from "react-redux";

export default function GymGuide() {
  const [gymGuideList, setGymGuideList] = useState([]);
  const dispatch = useDispatch();
  const [formData, setFormData] = useState({
    file: "",
    description: "",
  });

  useEffect(() => {
    getData();
  }, []);

  const getData = async () => {
    await http
      .get(apisPath?.admin?.gymGuide + "s")
      .then(async (res) => {
        // console.log(res?.data);
        setGymGuideList(res?.data?.gymGuideList);
      })
      .catch((err) => {
        console.log(err);
      });
  };

  const uploadData = async () => {
    await http
      .post(apisPath?.admin?.gymGuide, formData)
      .then((res) => {
        // console.log(res);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        setFormData({
          file: "",
          description: "",
        });
        getData();
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  const deleteData = async (index) => {
    await http
      .delete(`${apisPath?.admin?.gymGuide}/${index}`)
      .then(async (res) => {
        // console.log(res);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        getData();
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  const uploadPdfRef = useRef(null);
  return (
    <div className="gym_guide">
      <h3 className="gym_guide__heading page_heading">Gym guide</h3>
      <div className="gym_guide__content">
        <div className="gym_guide__content__upload">
          <div
            className="gym_guide__content__upload__logo"
            onClick={() => uploadPdfRef?.current?.click()}
          >
            <FileUploadIcon />
            <span>Upload PDF</span>
          </div>
          <input
            type="file"
            style={{ display: "none" }}
            ref={uploadPdfRef}
            onChange={async (e) => {
              await uploadImage(e)
                .then((res) => {
                  setFormData((prev) => {
                    return { ...prev, file: res?.url };
                  });
                })
                .catch((err) => {
                  console.log(err);
                });
            }}
          />
          {formData?.file !== "" && (
            <div className="gym_guide__content__upload__pdf gym_guide__content__upload__logo">
              <img src={PdfLogo} alt="PDF" />
            </div>
          )}
        </div>

        <div className="gym_guide__content__description">
          <h4 className="gym_guide__content__heading page_subheading">
            Description
          </h4>
          <div className="gym_guide__content__description__content">
            <textarea
              name="description"
              cols="100"
              rows="10"
              placeholder="Enter here"
              value={formData?.description}
              onChange={(el) => {
                setFormData((prev) => {
                  return { ...prev, description: el?.target?.value };
                });
              }}
            ></textarea>
            {/* <button className="button-border-red">
              <EditIcon /> Edit
            </button> */}
            <button className="button-red" onClick={uploadData}>
              Submit
            </button>
          </div>
        </div>

        <div className="gym_guide__content__gym_guide_list">
          <h4 className="gym_guide__heading page_subheading">Gym guide list</h4>
          <div className="gym_guide__content__gym_guide_list__content">
            {gymGuideList?.length > 0 ? (
              gymGuideList?.map((item, index) => {
                return (
                  <GymGuideList
                    file={item?.file}
                    key={index}
                    deleteData={() => deleteData(item?.id)}
                  />
                );
              })
            ) : (
              <div className="no_data_found">No Data Found</div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

const GymGuideList = ({ file, deleteData }) => {
  return (
    <div className="gym_guide_card">
      <a href={file} target="_blank">
        <div className="gym_guide_card__gym_guide_container">
          <img src={PdfLogo} alt="gym_guide" />
        </div>
      </a>
      <button className="button-red" onClick={deleteData}>
        Delete
      </button>
    </div>
  );
};
