import axios from "axios";
import { apisPath } from "../utils/path";
import { setLoading } from "../redux/reducer/LoadingReducer";
import store from "../redux/store";



const http = axios?.create({
    // baseURL: "https://bignlean.shellcode.cloud/",
    baseURL: "https://api.bignlean.com/",

});

http.interceptors.request.use(config => {
    store.dispatch(setLoading(true));
    return config;
}, error => {
    store.dispatch(setLoading(false));
    return Promise.reject(error);
});

// Response interceptor
http.interceptors.response.use(response => {
    store.dispatch(setLoading(false));
    return response;
}, error => {
    store.dispatch(setLoading(false));
    return Promise.reject(error);
});

const uploadImage = (e) => {
    let file = e?.target?.files[0];
    return new Promise((resolve, reject) => {
        let formData = new FormData();
        formData?.append('file', file)
        http?.post(apisPath?.admin?.upload, formData).then((res) => {
            resolve({ url: res?.data?.fileUrl })
        }).catch((err) => {
            reject(err)
        })
    })
}

export default http;
export { uploadImage };
